        let parts: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let mut nums: Vec<int> = []
        let mut i = 1
        while i < parts.len() {
            nums.push(parts[i].parse::<int>().unwrap_or(0))
            i += 1
        }
        let d: int = if parts[0] == "square" {
            show(Square { s: nums[0] })
        } else if parts[0] == "rect" {
            show(Rect { w: nums[0], h: nums[1] })
        } else if parts[0] == "rtri" {
            show(Rtri { a: nums[0], b: nums[1] })
        } else {
            show(Trap { a: nums[0], b: nums[1], h: nums[2] })
        }
