use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}
impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}
impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}
impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn show(sh: &dyn Shape) -> int {
    println("{} corners={} area2={}", sh.name(), sh.corners(), sh.double_area())
    sh.double_area()
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total: int = 0
    let mut best: int = -1
    let mut best_name = ""
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let mut nums: Vec<int> = []
        let mut i = 1
        while i < parts.len() {
            nums.push(parts[i].parse::<int>().unwrap_or(0))
            i += 1
        }
        let d: int = if parts[0] == "square" {
            show(&Square { s: nums[0] })
        } else if parts[0] == "rect" {
            show(&Rect { w: nums[0], h: nums[1] })
        } else if parts[0] == "rtri" {
            show(&Rtri { a: nums[0], b: nums[1] })
        } else {
            show(&Trap { a: nums[0], b: nums[1], h: nums[2] })
        }
        total += d
        if d > best {
            best = d
            best_name = parts[0].clone()
        }
    }
    println("total area2={}", total)
    if best < 0 {
        println("largest=none")
    } else {
        println("largest={} area2={}", best_name, best)
    }
}
